import{_ as e,o as i,c as a,a3 as t}from"./chunks/framework.D1GAkLkK.js";const k=JSON.parse('{"title":"Install","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/install.md","filePath":"getting-started/install.md"}'),h={name:"getting-started/install.md"};function n(o,s,l,r,p,d){return i(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h1><p>OpsTruss is one binary, for Linux and macOS on amd64 and arm64. On Windows it runs in WSL2.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>OpsTruss runs programs with <code>sh</code>, and fetches the <a href="./../plugins">catalog</a> with <code>git</code>. Each plugin needs the programs of its tool in <code>PATH</code>: <code>tofu</code> and <code>jq</code> for <code>tofu</code>, and <code>docker</code> with Compose v2 and <code>jq</code> for <code>compose</code>. <code>opstruss doctor</code> checks them for a project.</p><h2 id="with-mise" tabindex="-1">With mise <a class="header-anchor" href="#with-mise" aria-label="Permalink to &quot;With mise&quot;">​</a></h2><p><a href="https://mise.jdx.dev" target="_blank" rel="noreferrer">mise</a> pins the version of OpsTruss in the <code>mise.toml</code> of a project, next to the versions of the tools that the project runs, such as <code>tofu</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> use</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github:opstruss/opstruss@0.1.0</span></span></code></pre></div><p><code>mise use -g</code> installs it for every directory.</p><h2 id="from-a-release" tabindex="-1">From a release <a class="header-anchor" href="#from-a-release" aria-label="Permalink to &quot;From a release&quot;">​</a></h2><p>Every <a href="https://github.com/opstruss/opstruss/releases" target="_blank" rel="noreferrer">release</a> has an archive per platform, <code>checksums.txt</code>, and a build attestation of each archive. With the <a href="https://cli.github.com" target="_blank" rel="noreferrer">GitHub CLI</a>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">0.1.0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">archive</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">opstruss_</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\${version}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">_linux_amd64.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;v</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$version</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opstruss/opstruss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pattern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$archive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pattern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checksums.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ignore-missing</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checksums.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attestation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$archive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opstruss/opstruss</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$archive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opstruss</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/bin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opstruss</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/bin/</span></span></code></pre></div><p>On macOS, <code>shasum -a 256 --ignore-missing -c checksums.txt</code> checks the archive, and the archive is <code>opstruss_\${version}_darwin_arm64.tar.gz</code> on Apple silicon. <code>~/.local/bin</code> must be in <code>PATH</code>, which macOS does not do by itself: add <code>export PATH=&quot;$HOME/.local/bin:$PATH&quot;</code> to the profile of the shell, or install it with <code>sudo install opstruss /usr/local/bin/</code>.</p><h2 id="with-go" tabindex="-1">With Go <a class="header-anchor" href="#with-go" aria-label="Permalink to &quot;With Go&quot;">​</a></h2><p>Go 1.27 or newer builds it from source:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github.com/opstruss/opstruss@latest</span></span></code></pre></div><h2 id="check" tabindex="-1">Check <a class="header-anchor" href="#check" aria-label="Permalink to &quot;Check&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">opstruss</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span></code></pre></div><p><code>opstruss --version</code> prints the same. <code>opstruss doctor</code>, in a project, says whether the programs that the project needs are in <code>PATH</code>, and where the key of this machine is.</p><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><p>Install the new version the same way, as <code>mise use github:opstruss/opstruss@&lt;version&gt;</code>. Before 1.0, a minor release can ask something of a project: the <a href="https://github.com/opstruss/opstruss/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">changelog</a> says so first, under &quot;Upgrade notes&quot;. A daemon keeps running the binary that started it: run <code>opstruss stop</code>, then <code>opstruss up -d</code>, in each project whose daemon runs.</p><h2 id="shell-completion" tabindex="-1">Shell completion <a class="header-anchor" href="#shell-completion" aria-label="Permalink to &quot;Shell completion&quot;">​</a></h2><p><code>opstruss --completion &lt;shell&gt;</code> prints the completion script for bash, zsh, or fish, which completes commands, the tasks of the project, units, stacks, and runs:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># bash, in ~/.bashrc</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">opstruss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --completion</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># zsh, in ~/.zshrc</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">opstruss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --completion</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zsh)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># fish</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">opstruss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --completion</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fish</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/fish/completions/opstruss.fish</span></span></code></pre></div><h2 id="editor-support" tabindex="-1">Editor support <a class="header-anchor" href="#editor-support" aria-label="Permalink to &quot;Editor support&quot;">​</a></h2><p>The schema of <code>opstruss.yaml</code> gives completion and checks in editors that use the YAML language server, such as VS Code with the YAML extension. <code>opstruss init</code> writes the line that names it at the top of the file, with the schema of its version:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># yaml-language-server: $schema=https://opstruss.github.io/v0.1/schema/project.json</span></span></code></pre></div><p>The schema of <code>opstruss.plugin.yaml</code> is <code>plugin.json</code> in the same place.</p><h2 id="files-and-directories" tabindex="-1">Files and directories <a class="header-anchor" href="#files-and-directories" aria-label="Permalink to &quot;Files and directories&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Holds</th><th>Back up</th></tr></thead><tbody><tr><td><code>.opstruss/</code> of a project</td><td>the state of its stacks, the records and logs of its runs, the daemon of each stack</td><td><code>.opstruss/state/</code></td></tr><tr><td><code>~/Library/Application Support/opstruss/age/keys.txt</code> on macOS, <code>~/.config/opstruss/age/keys.txt</code> on Linux</td><td>the age key of this machine, which opens the sensitive values of the state; <code>$OPSTRUSS_AGE_KEY_FILE</code> names another file</td><td>yes</td></tr><tr><td><code>~/.opstruss/</code></td><td>the cache of fetched plugins, and the id of this machine</td><td>no</td></tr></tbody></table><p><code>opstruss doctor</code> shows where the age key is.</p><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><p>Take the stacks down first, with <code>opstruss destroy --stack &lt;stack&gt;</code> in each project, and stop their daemons with <code>opstruss stop</code>. Then remove the binary (<code>mise uninstall github:opstruss/opstruss</code>, or the file you installed) and <code>~/.opstruss/</code>. The age key and <code>.opstruss/</code> of each project are the only way to open what the state keeps; remove them only when no stack of any project needs them.</p><h2 id="without-mise" tabindex="-1">Without mise <a class="header-anchor" href="#without-mise" aria-label="Permalink to &quot;Without mise&quot;">​</a></h2><p>mise is one way to put OpsTruss and the tools of a project in <code>PATH</code>, and to load a <code>.env</code> file. OpsTruss needs neither: any package manager can install the tools, since <code>requires:</code> only checks that a program is in <code>PATH</code>, and <code>doctor</code> shows where each one is. The pages that use mise say what to do without it.</p>`,34)])])}const u=e(h,[["render",n]]);export{k as __pageData,u as default};
